namespace CheckoutPricing.Application.Checkout;

public enum CustomerTier { Standard, Gold }

public sealed record CalculatePayableTotalQuery(CustomerTier Tier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    // Compile-only stub: no discount behaviour yet.
    public decimal Handle(CalculatePayableTotalQuery query) => query.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application.Checkout;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void S1_Gold_customer_with_100_00_subtotal_pays_95_00()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalQuery(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
